import{_ as l,h as r,i as e,c as i,v as t,p as d,x as n,m as s,e as p,S as m}from"./chunks/framework.Dvtg8yj2.js";const u=JSON.parse('{"title":"vLLM 与 PagedAttention","description":"","frontmatter":{"title":"vLLM 与 PagedAttention","date":"2026-09-03T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/vllm-paged.md","filePath":"llm/vllm-paged.md","lastUpdated":1788454257000}'),h={name:"llm/vllm-paged.md"};function A(c,a,g,_,P,B){const o=r("Mermaid");return e(),i("div",null,[a[1]||(a[1]=t('<h1 id="vllm-与-pagedattention" tabindex="-1">vLLM 与 PagedAttention <a class="header-anchor" href="#vllm-与-pagedattention" aria-label="Permalink to &quot;vLLM 与 PagedAttention&quot;">​</a></h1><div class="epigraph"><p>把一条请求的 KV 切成定长块，块不必在物理上连续；注意力核带着块表去读，就像 CPU 带着页表访问虚拟内存。</p><footer>—— Kwon 等，PagedAttention，SOSP 2023</footer></div><p>注意力公式不要求键值张量在地址上相邻，要求的是按位置取出 \\(k_j,v_j\\) 再与 \\(q\\) 做 <a href="/llm/sdpa">缩放点积</a>。服务系统却长期把 KV 当成一块连续缓冲，因为深度学习框架默认张量连续。于是每条请求按最大长度预留，碎片和无法共享把有效容量吃掉。PagedAttention 把 OS 的分页搬进来：逻辑序列是虚拟地址空间，定长 KV 块是页，块表是页表，物理池是 DRAM。vLLM 是建立在这套寻址上的服务引擎。本篇写块、表、共享与核，调度见 <a href="/llm/vllm-scheduler">调度器</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>一条序列的 KV 随解码增长，最终长度在结束前未知。连续分配若按 \\(n_{\\max}\\)（例如 2048）一次划出，内部碎片是「用不到的上限」；即便知道最终长度，整段生命周期内未写满的前半仍不能借给别人，这是预留槽浪费。不同请求的预留长度不同，分配器还会留下夹在中间的外部空洞。Kwon 等人的剖面里，现有系统 KV 空间里真正存着有效 token 状态的比例可以低到约 20%–38%。</p><p>第二类损失是不能共享。并行采样时多条输出共用同一提示的 KV；束搜索里不同束在分叉前共享前缀，分叉后部分块仍相同。连续张量无法让两张「请求私有缓冲」指向同一段物理内存，除非显式拷贝。拷贝既费带宽又复制了本该只读的提示块。</p><h3 id="虚拟连续、物理分页" tabindex="-1">虚拟连续、物理分页 <a class="header-anchor" href="#虚拟连续、物理分页" aria-label="Permalink to &quot;虚拟连续、物理分页&quot;">​</a></h3><p>把序列位置 \\(0\\ldots n-1\\) 切成每 \\(B\\) 个 token 一块。逻辑块号 \\(i\\) 对应位置 \\([iB,(i+1)B)\\)。物理上，这些块可以落在池里任意空闲页。注意力在位置 \\(j\\) 需要 \\(k_j\\) 时，查块表得到物理块 \\(p=\\mathrm{table}[\\lfloor j/B\\rfloor]\\)，再取块内偏移 \\(j \\bmod B\\)。对核来说，多了一次间接；对分配器来说，所有页一样大，外部碎片消失，内部碎片上界是一块里未填满的槽。</p><p><span class="marginnote">类比要停在「页」这一层。OS 还有缺页中断、多级页表、TLB。vLLM 的块表通常是每序列一张扁平表，缺页对应调度器去分配或去抢占，不会在注意力核里走一次操作系统中断。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>物理池在每层、每个 KV 头（或按实现打包后的布局）上切成块。一块含 \\(B\\) 个位置的键与值。论文示例常用 \\(B=16\\)。\\(B\\) 太小，表项多、核 gather 碎；\\(B\\) 太大，内部碎片与共享粒度一起变粗。分配发生在序列需要新位置时：当前尾块未满则只写偏移，满了才向池申请一个空闲物理块并追加到块表。释放在序列结束或抢占时：引用计数减到零的物理块回池。</p><p>Copy-on-write 处理共享。块表可以让序列 A、B 的前若干逻辑块指向同一物理页，引用计数为 2。谁先要在该页上写入（例如分叉后的第一个生成位置落在未满块里，或新块本该覆盖共享尾），就先复制该页再写，引用计数拆开。这样提示段始终只存一份，束之间的共同前缀也只存一份，直到真正分叉。</p>',12)),(e(),d(m,null,{default:n(()=>[p(o,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20LR%0A%20%20POS%5B%22%E9%80%BB%E8%BE%91%E4%BD%8D%E7%BD%AE%20j%22%5D%20--%3E%20DIV%5B%22%E5%9D%97%E5%8F%B7%20floor(j%2FB)%22%5D%0A%20%20DIV%20--%3E%20BT%5B%22%E5%9D%97%E8%A1%A8%22%5D%0A%20%20BT%20--%3E%20PHY%5B%22%E7%89%A9%E7%90%86%E5%9D%97%20p%22%5D%0A%20%20PHY%20--%3E%20OFF%5B%22%E5%9D%97%E5%86%85%E5%81%8F%E7%A7%BB%20j%20mod%20B%22%5D%0A%20%20OFF%20--%3E%20K%5B%22%E5%8F%96%E5%87%BA%20k_j%20%2F%20v_j%22%5D%0A%20%20Q%5B%22%E6%9F%A5%E8%AF%A2%20q%22%5D%20--%3E%20ATTN%5B%22PagedAttention%22%5D%0A%20%20K%20--%3E%20ATTN%0A"})]),fallback:n(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h3 id="核必须接受非连续的-k、v" tabindex="-1">核必须接受非连续的 K、V <a class="header-anchor" href="#核必须接受非连续的-k、v" aria-label="Permalink to &quot;核必须接受非连续的 K、V&quot;">​</a></h3><p>标准 SDPA 假设 \\(K,V\\) 是形状整齐的张量。PagedAttention 的实现是：对每个查询，按块表列出本序列已写满的块加一个可能未满的尾块，在块内做局部点积，再在块间归约 softmax。FlashAttention 一类分块算法仍然适用，只是外层循环的「K 的一块」变成「物理页」而不是地址连续的切片。数值与连续实现应对齐；不对齐是实现 bug，不是分页语义。</p><p>跨请求前缀相同（同一系统提示）时，调度器若识别出公共前缀，也可以把新请求的块表前段指到已有物理页。vLLM 论文把这写成分页使能的能力；自动、按 token 序列做最长前缀匹配并在树里维护 LRU，是 <a href="/llm/sglang">RadixAttention</a> 的主线。两者相容：radix 树的节点可以指向 PagedAttention 的物理块。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>近零浪费是相对「按 \\(n_{\\max}\\) 连续预留」而言。内部碎片期望大约是半块，即 \\(B/2\\) 个 token 槽，而不是 \\(n_{\\max}-n_{\\mathrm{actual}}\\)。外部碎片为零（定长）。预留槽不存在：未来的生成尚未发生时，那些页仍在池里，可以借给此刻更长的别人。于是同样的 HBM，运行中序列数可以明显更多，迭代级批变大，decode 的权重读取被摊薄。这是吞吐上来的机制，不是注意力算得更快。</p><p>共享把「复杂解码更吃显存」变成「复杂解码更该用分页」。论文指出并行采样可共享提示 KV，束搜索的共享比例随解码演变，实验中束搜索场景可省下相当比例的 KV（文中提到高达约 55% 的量级，取决于负载）。没有 CoW，分页只解决碎片；有 CoW，分页才解决算法带来的重复。</p><p><span class="marginnote">OPT-13B 上一个 token 的 KV 约 800 KB（论文按隐宽 5120、40 层、FP16 计算）。\\(n_{\\max}=2048\\) 时一条请求的连续预留约 1.6 GB。块大小 16 则按需领取，结束即还。数量级说明为什么碎片不是边角料：池里多出来的几个 GB 直接变成可并发条数。</span></p><h3 id="与虚拟内存的差异要写清" tabindex="-1">与虚拟内存的差异要写清 <a class="header-anchor" href="#与虚拟内存的差异要写清" aria-label="Permalink to &quot;与虚拟内存的差异要写清&quot;">​</a></h3><p>GPU 设备内存通常没有 CPU 那种透明换页。vLLM 的「换出」是调度器显式把某些序列的块拷到主机，再从块表摘掉。注意力核不会在访问缺失页时暂停去磁盘。因此 PagedAttention 不是把 CUDA 变成 Linux，而是把 <strong>页表这个数据结构</strong> 和 <strong>按需分配这条政策</strong> 借到 KV 上。透明换页若做成每次注意力都可能缺页，ITL 会不可控。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>分页不降低数学上的 KV 字节数：层数、头数、头维、精度仍决定下限，见 <a href="/llm/kv-as-long-context">KV 作为长上下文</a>。GQA、MLA、KV 量化是改公式或改精度；分页是改布局。四者正交，可以叠，不要互相替代着宣传。</p><p>块大小与核实现绑定。服务端常用十几到几十 token 一块；若把块改成 1，共享最细，间接最重。SGLang 的 radix 描述里甚至讨论过以 token 为页的树，那是另一套索引，底层仍可落在分页池上。多模态前缀、音频 token 若长度单位不是「一个文本 token 一个槽」，块对齐要重做，不能假设文本核直接吃图像块，对照 <a href="/llm/qwen3-asr-vllm">ASR 挂 vLLM</a> 时前缀增长的是音频槽。</p><p><span class="marginnote">「接近零浪费」不包括权重、激活、CUDA Graph 工作区，也不包括你为了省事把块开得太大。它比较的是 KV 池内部的碎片结构。把整卡利用率 90% 说成 PagedAttention 的功劳，会把权重常驻和池管理混为一谈。</span></p><p>评测数字 2–4× 相对的是当时的 FasterTransformer 与 Orca，同一延迟水平下的吞吐。今日对照 <a href="/llm/sglang">SGLang</a> 或 <a href="/llm/tensorrt-llm">TensorRT-LLM</a>，差的是前缀缓存、融合核、量化与投机，不是「谁还在用连续 KV」。新引擎几乎都分页了；再写一篇「分页击败连续预留」需要钉住仍在预留 \\(n_{\\max}\\) 的基线。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>PagedAttention 用定长 KV 块加块表存储非连续键值，注意力按逻辑位置间接取值。</li><li>定长块消灭外部碎片；按需分配把内部碎片限制在一块之内，并取消按 \\(n_{\\max}\\) 预留。</li><li>块表引用计数与 CoW 使提示与束前缀可共享，复杂解码不再复制整段 KV。</li><li>公式仍是 SDPA；加速来自更大的可行 batch，不是更少的 FLOPs。</li><li>换出是调度器显式拷贝，不是 GPU 缺页中断。</li><li>出处：Kwon et al., <em>Efficient Memory Management for Large Language Model Serving with PagedAttention</em>, SOSP 2023（arXiv:2309.06180）。</li></ul>',16))])}const E=l(h,[["render",A]]);export{u as __pageData,E as default};
